test.describe('2.4 Registration — Variations', () => {
  test('2.4.1: Duplicate email is rejected', async ({ request }) => {
    // Try to register with an email that already exists (the issuer)
    const res = await request.post(`${getBaseUrl()}api/auth/register`, {
      data: {
        email: CREDENTIALS.issuer.email,
        password: TEST_PASSWORD,
        confirmPassword: TEST_PASSWORD,
        name: 'Duplicate User',
      },
      failOnStatusCode: false,
    });

    const status = res.status();
    // Should be a conflict (409) or bad request (400) or similar
    expect(status).not.toBe(201);
    expect(status).not.toBe(200);
  });

  test('2.4.2: Weak password is rejected', async ({ request }) => {
    const res = await request.post(`${getBaseUrl()}api/auth/register`, {
      data: {
        email: uniqueEmail(),
        password: '123',
        confirmPassword: '123',
        name: 'Weak Password User',
      },
      failOnStatusCode: false,
    });

    const status = res.status();
