   * carrying an unissued `state`, and one carrying an already-consumed `state`,
   * must both be refused BEFORE `exchangeCode` — asserted by counting
   * `exchangeCode` invocations, not by reading a status code, because the route
   * already answers 400 for an unconfigured provider.
   */
  test('2.7.5: OAuth callback with an unissued state is refused and never mints (does NOT cover state validation — KS-722)', async ({ request }) => {
    const res = await request.get(
      `${getBaseUrl()}api/auth/social/google/callback?state=tampered_csrf_token&code=fake_code`,
      { failOnStatusCode: false }
    );

    const status = res.status();
    const body = await res.text();

    // Stronger than the `< 500` this replaced: that was also satisfied by a 200
    // and by a redirect, so it could not fail.
    expect(
      status,
      `OAuth callback must answer a client-error refusal, got ${status}: ${body.slice(0, 200)}`,
    ).toBeGreaterThanOrEqual(400);
    expect(status).toBeLessThan(500);

    // The property that actually matters, asserted unconditionally rather than
    // inside an `if (status === 200)` that never ran.
    expect(body, 'OAuth callback must never return an access token').not.toContain('accessToken');
    expect(body, 'OAuth callback must never return a refresh token').not.toContain('refreshToken');
  });
});

