test.describe.serial('2.8 MFA / TOTP', () => {
  let authToken: string | undefined;
  let mfaSecret: string | undefined;

  // Clean up MFA state after all tests to avoid polluting other test suites
  test.afterAll(async ({ request }) => {
    if (!authToken) return;
    // Attempt to disable MFA regardless of whether tests passed
    await apiRequest(request, 'POST', `${getBaseUrl()}api/auth/mfa/disable`, {
      token: authToken,
      data: { password: CREDENTIALS.issuer.password },
    }).catch(() => {});
  });

  test('2.8.1: MFA setup endpoint exists and returns QR/secret', async ({ request }) => {
    // Login with a fresh request (bypass cache) to get a unique session.
    // This avoids issues where the cached token has an expired/invalidated session.
    const loginResponse = await request.post(`${getBaseUrl()}api/auth/login`, {
      data: { email: CREDENTIALS.issuer.email, password: CREDENTIALS.issuer.password },
      failOnStatusCode: false,
    });
    let loginBody: any = {};
    try { loginBody = await loginResponse.json(); } catch {}
    authToken = loginBody?.data?.accessToken || loginBody?.accessToken || loginBody?.token;

    if (!authToken) {
      // If login failed (e.g., MFA required from previous run), use cached token
      const cached = await apiLogin(request, CREDENTIALS.issuer.email, CREDENTIALS.issuer.password);
      authToken = cached.accessToken;
    }

    if (!authToken) {
      console.warn('No auth token obtained for MFA tests. Cookie-based auth may be in use.');
    }

    // First, disable MFA if already enabled (from a previous test run)
    if (authToken) {
      const disableRes = await apiRequest(request, 'POST', `${getBaseUrl()}api/auth/mfa/disable`, {
        token: authToken,
        data: { password: CREDENTIALS.issuer.password },
      });
      if (disableRes.status === 200) {
        console.log('MFA was already enabled — disabled it for a clean test.');
        // Re-login after MFA state change to get a fresh token
        const freshLogin = await request.post(`${getBaseUrl()}api/auth/login`, {
          data: { email: CREDENTIALS.issuer.email, password: CREDENTIALS.issuer.password },
          failOnStatusCode: false,
        });
        let freshBody: any = {};
        try { freshBody = await freshLogin.json(); } catch {}
        authToken = freshBody?.data?.accessToken || freshBody?.accessToken || freshBody?.token;
      }
    }

    // Try /api/auth/mfa/setup/start (actual endpoint) then fallbacks
    const endpoints = [
      `${getBaseUrl()}api/auth/mfa/setup/start`,
      `${getBaseUrl()}api/auth/mfa/setup`,
      `${getBaseUrl()}api/auth/2fa/setup`,
    ];

    let found = false;
    for (const endpoint of endpoints) {
      const res = await apiRequest(request, 'POST', endpoint, { token: authToken });
      if (res.status !== 404) {
        // Accept 200/201 (success) or 409 (already enabled — informational)
        expect([200, 201]).toContain(res.status);
        // Response: { success, data: { secret, otpAuthUri } }
        const data = res.body?.data || res.body;
        mfaSecret = data?.secret || data?.totpSecret;
        const hasSetupInfo = data?.secret || data?.qrCode || data?.otpAuthUri || data?.otpauthUrl;
        expect(hasSetupInfo).toBeTruthy();
        console.log('MFA secret obtained from:', endpoint);
        found = true;
        break;
      }
    }

    if (!found) {
      console.warn('MFA setup endpoint not found at any path');
    }
  });

  test('2.8.2: Verify TOTP with valid code succeeds', async ({ request }) => {
    if (!mfaSecret || !authToken) {
      expect(false, 'BLOCKER: MFA secret not available — MFA setup endpoint may not be implemented').toBeTruthy();
      return;
    }

    const validCode = generateSync({ secret: mfaSecret });

    // Try /api/auth/mfa/setup/verify (actual endpoint for setup verification)
    //
    // KS-622 (#745 review): /api/auth/mfa/verify is deliberately NOT in this list any
    // more. It is retired and answers 410 unconditionally, and this loop breaks on
    // `status !== 404` then asserts [200, 201]. So if setup/verify ever 404s, the loop
    // would land on the retired route and fail on toContain(410) — a false red about
    // TOTP verification caused entirely by an endpoint that no longer participates.
    // General shape worth remembering: a route that used to 404 for everything and now
    // answers non-404 for everything inverts every `!== 404` probe that lists it.
    const endpoints = [
      `${getBaseUrl()}api/auth/mfa/setup/verify`,
      `${getBaseUrl()}api/auth/2fa/verify`,
    ];

    let found = false;
    for (const endpoint of endpoints) {
      const res = await apiRequest(request, 'POST', endpoint, {
        token: authToken,
        data: { totpCode: validCode, code: validCode },
      });
      if (res.status !== 404) {
        expect([200, 201]).toContain(res.status);
        found = true;
        break;
      }
    }

    if (!found) {
      console.warn('MFA verify endpoint not found');
    }
  });

  test('2.8.3: Wrong TOTP code is rejected', async ({ request }) => {
    // Get a fresh token since previous tests may have changed MFA state
    if (!authToken) {
      const loginRes = await apiLogin(request, CREDENTIALS.issuer.email, CREDENTIALS.issuer.password);
      authToken = loginRes.accessToken;
    }

    // The /api/auth/mfa/verify endpoint is for login MFA verification (requires userId in body).
    // The /api/auth/mfa/setup/verify endpoint is for setup verification (requires totpCode).
    // Test the setup/verify endpoint with a wrong code.
    const res = await apiRequest(request, 'POST', `${getBaseUrl()}api/auth/mfa/setup/verify`, {
      token: authToken,
      data: { totpCode: '000000' },
    });

    if (res.status === 404) {
      // Fallback: try the login MFA verify endpoint
      const altRes = await apiRequest(request, 'POST', `${getBaseUrl()}api/auth/mfa/verify`, {
        token: authToken,
        data: { code: '000000', userId: 'non-existent-user' },
      });

      // KS-622: retired — 410 Gone, exactly.
      expect(altRes.status).toBe(410);
      return;
    }

    expect(res.status).not.toBe(200);
  });

  test('2.8.4: retired /api/auth/mfa/verify answers 410 for an expired TOTP', async ({ request }) => {
    // KS-622 (#745 review): this was a 35-second sleep behind test.slow(), waiting for
    // a TOTP to expire before asserting a status the handler returns unconditionally.
    // The route is retired — it does not look at the code, so waiting proves nothing
    // and cost 35s of wall clock on every run. Kept as a retirement guard with one
    // request; the assertion is deliberately exact, since a bare "not 200" would keep
    // passing if the endpoint ever came back. TOTP expiry itself now belongs to
    // POST /api/auth/login, which verifies the password first.
    if (!mfaSecret) {
      expect(false, 'BLOCKER: MFA secret not available — MFA setup endpoint may not be implemented').toBeTruthy();
      return;
    }

    const code = generateSync({ secret: mfaSecret });
    const res = await apiRequest(request, 'POST', `${getBaseUrl()}api/auth/mfa/verify`, {
      token: authToken,
      data: { code, token: code },
    });
    expect(res.status).toBe(410);
  });

  test('2.8.5: MFA disable requires current TOTP', async ({ request }) => {
    const res = await apiRequest(request, 'POST', `${getBaseUrl()}api/auth/mfa/disable`, {
      token: authToken,
      data: {}, // No TOTP code provided
    });

    if (res.status === 404) {
      const altRes = await apiRequest(request, 'POST', `${getBaseUrl()}api/auth/2fa/disable`, {
        token: authToken,
        data: {},
      });

      if (altRes.status === 404) {
        console.warn('MFA disable endpoint not found.');

      }

      // Should require TOTP code to disable — reject without one
      expect(altRes.status).not.toBe(200);
      return;
    }

    // Disabling MFA without providing current TOTP code should fail
    expect(res.status).not.toBe(200);
  });

  test('2.8.6: retired /api/auth/mfa/verify answers 410 to a wrong TOTP', async ({ request }) => {
    // KS-622 (#745 review): this looped ten identical requests at a handler that
    // returns 410 unconditionally, then warned when no 429 appeared — a rate-limit
    // observation that the retired route can no longer produce. One request is the
    // whole of what it can still prove.
    //
    // Brute-force resistance for the second factor now belongs to
    // POST /api/auth/login. As of this PR the (email, /24) lockout DOES engage there:
    // both MFA failure paths call recordFailure (services/auth/src/routes/auth.ts),
    // which before this change only ran at the password stage. See BACKLOG.md for the
    // login-side e2e coverage gap that remains.
    const res = await apiRequest(request, 'POST', `${getBaseUrl()}api/auth/mfa/verify`, {
      token: authToken,
      data: { code: '123456', token: '123456' },
    });
    expect(res.status).toBe(410);
  });
});

