      (h) => h.name.toLowerCase() === 'set-cookie'
    );

    if (setCookieHeaders.length === 0) {
      console.warn('No Set-Cookie headers returned from login — tokens may be in response body only.');
      // Still a valid architecture (JWT in body), but document it
      const body = await res.json().catch(() => null);
      if (body?.accessToken || body?.token) {
        console.log('Auth uses JWT in response body (not cookies). Verify client stores securely.');
      }
      return;
    }

    // Check that auth-related cookies have HttpOnly flag
    for (const header of setCookieHeaders) {
      const cookieValue = header.value.toLowerCase();
      // Only check auth-related cookies (token, session, jwt, auth)
      const isAuthCookie = /token|session|jwt|auth|sid/i.test(cookieValue);
      if (isAuthCookie) {
        expect(cookieValue).toContain('httponly');
        console.log(`Cookie "${header.value.split('=')[0]}" has HttpOnly flag.`);

        // Also check for Secure flag (important for production)
        if (!cookieValue.includes('secure')) {
          console.warn(`Cookie "${header.value.split('=')[0]}" missing Secure flag.`);
        }

        // Check for SameSite
        if (!cookieValue.includes('samesite')) {
          console.warn(`Cookie "${header.value.split('=')[0]}" missing SameSite attribute.`);
        }
      }
    }
  });

  test('2.9.2: JWT delivery mechanism — check response vs cookie', async ({ request }) => {
